using System;
using System.Collections.Generic;
namespace Downfield {
public class CoachRecord {
 public string Name="COACH";public int Wins,Losses,Ties,PlayoffWins,Championships,Skin=1,Hair,Hat=1,Outfit;public bool Initialized;
 public float WinPercent {get{return Wins+Losses+Ties==0?0:100f*(Wins+Ties*.5f)/(Wins+Losses+Ties);}}
}
public class TeamSeason {public int Season,Team,W,L,T,PF,PA,Seed;public bool Champion;public string Name="";}
public class SeasonAward {public int Season,Team,PlayerId=-1,Number,OVR,Speed,Hands,Power;public string Role="";public string Type="",Winner="",Club="",Coach="";public float Score;}
public class SeasonProduction {
 public int PlayerId,Team,PassYards,RushYards,RecYards,PassTD,RushTD,RecTD,Catches,Attempts,Completions,Picks,Games;public string Name="",Role="";
 public float OffenseScore {get{return PassYards*.045f+(RushYards+RecYards)*.1f+PassTD*5+(RushTD+RecTD)*10+Catches*.4f-Picks*2;}}
}
public partial class Franchise {
 public CoachRecord Coach=new CoachRecord();public List<TeamSeason> History=new List<TeamSeason>();public List<SeasonAward> Awards=new List<SeasonAward>();public List<SeasonProduction> Production=new List<SeasonProduction>();public int HistoryVersion=1;
 public void EnsureCareer(){if(Coach==null)Coach=new CoachRecord();if(Coach.Initialized)return;Coach.Initialized=true;foreach(Fixture g in Games)if(g.Played&&g.Involves(UserTeam)){int own=g.Home==UserTeam?g.HomeScore:g.AwayScore,other=g.Home==UserTeam?g.AwayScore:g.HomeScore;if(own>other){Coach.Wins++;if(g.Round>=11)Coach.PlayoffWins++;}else if(own<other)Coach.Losses++;else Coach.Ties++;}Coach.Championships=Titles;}
 public void NameCoach(string name){name=(name??"").Trim().ToUpperInvariant();if(name.Length==0)name="COACH";Coach.Name=name.Substring(0,Math.Min(16,name.Length));Save();}
 void CoachResult(Fixture g){EnsureCareer();int own=g.Home==UserTeam?g.HomeScore:g.AwayScore,other=g.Home==UserTeam?g.AwayScore:g.HomeScore;if(own>other){Coach.Wins++;if(g.Round>=11)Coach.PlayoffWins++;if(g.Round==13)Coach.Championships++;}else if(own<other)Coach.Losses++;else Coach.Ties++;}
 SeasonProduction ProductionFor(ClubPlayer p){SeasonProduction line=Production.Find(x=>x.PlayerId==p.Id);if(line==null){line=new SeasonProduction();line.PlayerId=p.Id;line.Team=p.Team;line.Name=p.Name;line.Role=p.Role;Production.Add(line);}line.Team=p.Team;return line;}
 public void AddBox(int team,List<BoxLine> box){foreach(ClubPlayer player in Squad(team))if(player.Slot>=0&&player.Slot<11&&player.InjuryWeeks==0)ProductionFor(player).Games++;foreach(BoxLine b in box){ClubPlayer p=Players.Find(x=>x.Id==b.PlayerId);if(p==null||p.Team!=team)continue;SeasonProduction line=ProductionFor(p);line.PassYards+=b.PassYards;line.RushYards+=b.RushYards;line.RecYards+=b.RecYards;line.PassTD+=b.PassTD;line.RushTD+=b.RushTD;line.RecTD+=b.RecTD;line.Catches+=b.Catches;line.Attempts+=b.Attempts;line.Completions+=b.Completions;line.Picks+=b.Picks;}}
 void SimulatedBox(Fixture game,int team,int score){Random r=new Random(Season*6731+game.Id*37+team*11);ClubPlayer qb=Starter(team,0),rb=Starter(team,1);if(qb==null||rb==null)return;int opponent=game.Opponent(team),defense=Rating(opponent,true),attack=Rating(team,false),totalTD=score/7;List<BoxLine> box=new List<BoxLine>();List<ClubPlayer> receivers=new List<ClubPlayer>();foreach(int slot in new int[]{2,3,4,10}){ClubPlayer p=Starter(team,slot);if(p!=null)receivers.Add(p);}double hands=0,speed=0;foreach(ClubPlayer p in receivers){hands+=p.Hands;speed+=p.Speed;}hands/=Math.Max(1,receivers.Count);speed/=Math.Max(1,receivers.Count);double passing=Math.Max(.25,Math.Min(.8,.52+(qb.Power-rb.Power)*.004+(team%3-1)*.08));int passingTD=0;for(int i=0;i<totalTD;i++)if(r.NextDouble()<passing)passingTD++;
  BoxLine q=new BoxLine();q.PlayerId=qb.Id;q.Attempts=16+r.Next(13)+(team%3)*2;double completion=Math.Max(.40,Math.Min(.82,.55+(qb.Hands-75)*.004+(qb.Power-75)*.002+(hands-75)*.002-(defense-75)*.003+(r.NextDouble()-.5)*.12));q.Completions=(int)Math.Round(q.Attempts*completion);q.PassYards=Math.Max(20,(int)(q.Completions*(8+r.Next(6)+(qb.Power-75)*.07+(speed-75)*.08-(defense-75)*.07)));q.PassTD=passingTD;q.Picks=(int)Math.Max(0,Math.Round(r.NextDouble()*2+(defense-qb.Power)*.035-.2));box.Add(q);
  BoxLine rush=new BoxLine();rush.PlayerId=rb.Id;rush.RushYards=Math.Max(8,(int)(25+r.Next(65)+(rb.Speed-75)*1.8+(rb.Power-75)*.8+(attack-defense)*1.1));rush.RushTD=totalTD-passingTD;box.Add(rush);
  double[] weights=new double[receivers.Count];double total=0;for(int i=0;i<receivers.Count;i++){ClubPlayer p=receivers[i];weights[i]=(1+(p.Speed-70)*.025+(p.Hands-70)*.035+(p.OVR-70)*.02)*(p.Role=="TE"?.8:1)*(.5+r.NextDouble()*1.2);total+=weights[i];}int leftYards=q.PassYards,leftCatches=q.Completions;List<BoxLine> catches=new List<BoxLine>();for(int i=0;i<receivers.Count;i++){BoxLine b=new BoxLine();b.PlayerId=receivers[i].Id;b.RecYards=i==receivers.Count-1?leftYards:Math.Min(leftYards,(int)Math.Round(q.PassYards*weights[i]/total));b.Catches=i==receivers.Count-1?leftCatches:Math.Min(leftCatches,(int)Math.Round(q.Completions*weights[i]/total));leftYards-=b.RecYards;leftCatches-=b.Catches;catches.Add(b);box.Add(b);}for(int td=0;td<passingTD&&catches.Count>0;td++){double pick=r.NextDouble()*total;int receiver=0;while(receiver<weights.Length-1&&pick>=weights[receiver])pick-=weights[receiver++];catches[receiver].RecTD++;}AddBox(team,box);}

 void ArchiveSeason(){if(History.Exists(x=>x.Season==Season))return;List<Standing> table=Table();Fixture final=Games.Find(x=>x.Round==13&&x.Played);if(final==null)return;foreach(Standing s in table){TeamSeason entry=new TeamSeason();entry.Season=Season;entry.Team=s.Team;entry.Name=Teams[s.Team].Name;entry.W=s.W;entry.L=s.L;entry.T=s.T;entry.PF=s.PF;entry.PA=s.PA;entry.Seed=Seeds.IndexOf(s.Team)+1;entry.Champion=final.Winner==s.Team;History.Add(entry);}SeasonAward title=new SeasonAward();title.Season=Season;title.Team=final.Winner;title.Type="CHAMPIONSHIP";title.Winner=Teams[title.Team].Name;title.Club=title.Winner;title.Coach=title.Team==UserTeam?Coach.Name:"";Awards.Add(title);
  SeasonProduction mvp=null,op=null;float bestM=-999,bestO=-999;foreach(SeasonProduction p in Production){Standing team=table.Find(t=>t.Team==p.Team);float value=AwardValue(p,"MVP"),offense=AwardValue(p,"OPOTY");if(value>bestM){bestM=value;mvp=p;}if(offense>bestO){bestO=offense;op=p;}}if(mvp!=null)AwardPlayer("MVP",mvp,bestM);if(op!=null)AwardPlayer("OPOTY",op,bestO);}
 void AwardPlayer(string type,SeasonProduction p,float score){SeasonAward award=new SeasonAward();award.Season=Season;award.Team=p.Team;award.Type=type;award.Winner=p.Name;award.Club=Teams[p.Team].Name;award.Coach=p.Team==UserTeam?Coach.Name:"";award.Score=score;award.PlayerId=p.PlayerId;award.Role=p.Role;ClubPlayer player=Players.Find(x=>x.Id==p.PlayerId);if(player!=null){award.Number=player.Number;award.OVR=player.OVR;award.Speed=player.Speed;award.Hands=player.Hands;award.Power=player.Power;}Awards.Add(award);}
 public bool JoinClub(int team){if(team<0||team>=12)return false;if(!Fired&&(Round!=0&&Round!=14||Round==0&&Games.Exists(g=>g.Played))){Notice="Change clubs between seasons.";return false;}if(!JobAvailable(team)){Notice="That club has no opening for you. Choose a club marked HIRING.";return false;}EnsureCareer();Business.Cash=Credits;ClubBusiness next=BusinessFor(team);UserTeam=team;Credits=next.Cash;if(Fired){Fired=false;DismissalReason="";next.Security=Math.Max(60,next.Security);next.JobGames=next.LossStreak=next.UnhappyGames=0;}Log(Coach.Name+" joins "+Club.Name+".");Save();return true;}
}
}
